            "sampleValue": "18 分钟"
          }
        },
        {
          "name": {
            "type": "string",
            "description": "第三项训练名称",
            "sampleValue": "瑜伽拉伸"
          },
          "remainingText": {
            "type": "string",
            "description": "第三项训练剩余时长展示文本",
            "sampleValue": "30 分钟"
          }
        }
      ],
      "reminderEntityId": {
        "type": "string",
        "description": "训练提醒对应的日历事件标识",
        "sampleValue": "fitness-reminder-today"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/flame_fill.svg",
      "description": "火焰实心图标，适合表达力量训练和运动消耗，可用于训练项识别。"
    },
    {
      "src": "resources/base/media/icon_run.png",
      "description": "运动跑步图标，适合表达跑步训练和运动健康场景，可用于训练项识别。"
    },
    {
      "src": "resources/base/media/stopwatch_fill.svg",
      "description": "秒表实心图标，适合表达计时训练、倒计时和剩余时长，可用于训练项识别。"
    }
  ]
}

